describe("resolveFeedbackAnchor - guardrail cases (synthetic)", () => {
  it("rejects a short excerpt that recurs many times rather than guessing (min-length gate)", () => {
    // "the" appears constantly; offsets are stale and there is no way to
    // disambiguate a 3-character excerpt by proximity alone.
    const chapterText = "the cat sat on the mat near the door by the window in the room by the the the";
    const result = resolveFeedbackAnchor("the", 500, 503, chapterText);
    assert.equal(result.status, "not-found");
  });

  it("rejects an ambiguous long-enough excerpt when two occurrences are too close in distance to prefer one (ambiguity gate)", () => {
    const gap = "x".repeat(1000); // large enough that tier-2's local window can't reach either occurrence
    const target = "this exact sentence appears twice in the chapter on purpose";
    const chapterText = gap + target + gap + target + gap;
    const pos1 = gap.length;
    const pos2 = gap.length + target.length + gap.length;
    const referenceOffset = Math.round((pos1 + pos2) / 2); // exactly equidistant -> ratio ~1, well above the 1/3 cutoff
    const result = resolveFeedbackAnchor(target, referenceOffset, referenceOffset + target.length, chapterText);
    assert.equal(result.status, "not-found");
  });

  it("accepts a unique long-enough excerpt found far from a stale stored offset (no blanket distance cap)", () => {
    // Mirrors Case B's shape: a substantial edit shifted the real content
    // thousands of characters away from where it used to be, but it's the
    // only occurrence in the document, so distance alone must not reject it.
    const target = "this distinctive sentence only appears once in this entire chapter";
    const chapterText = "z".repeat(5000) + target + "z".repeat(2000);
    const result = resolveFeedbackAnchor(target, 10, 10 + target.length, chapterText);
    assert.equal(result.status, "anchored-fuzzy");
    if (result.status !== "anchored-fuzzy") throw new Error("unreachable");
    assert.equal(result.method, "nearest-raw");
    assert.equal(result.start, 5000);
  });
});
